namespace ghidra.app.plugin.core.decompiler.taint.actions;



using docking;
using docking.action;
using docking.action;
using ghidra.app.plugin.core.decompile;
using ghidra.app.plugin.core.decompiler.taint;
using ghidra.util;

/**
 * Action triggered from a specific token in the decompiler window to mark a variable as a source or
 * sink and generate the requisite query. This can be an input parameter, a stack variable, a
 * variable associated with a register, or a "dynamic" variable.
 */
public class TaintClearAction : TaintAbstractDecompilerAction {

	private TaintPlugin plugin;

	public TaintClearAction(TaintPlugin plugin) : base("Clear Markers")
    {
		setHelpLocation(new HelpLocation(TaintPlugin.HELP_LOCATION, "TaintClear"));
		setPopupMenuData(new MenuData(new string[] { "Taint", "Clear" }, "Decompile"));
		setKeyBindingData(
			new KeyBindingData(KeyEvent.VK_S, DockingUtils.CONTROL_KEY_MODIFIER_MASK));
		this.plugin = plugin;
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		if (plugin.getTaintState() == null) {
			return false;
		}
		return true;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		plugin.getTaintState().clearMarkers();
		plugin.clearIcons();
		plugin.clearTaint();
		plugin.consoleMessage("taint cleared");
	}
}
